<content>/**
 * TypeScript Type Definitions for IBM BOB API
 * These types match the Backend Pydantic schemas
 */

// ============================================================================
// Common Types
// ============================================================================

export type JobStatus = 
  | 'pending'
  | 'processing'
  | 'completed'
  | 'failed'
  | 'cancelled';

export type AnalysisStage = 
  | 'parsing'
  | 'complexity_analysis'
  | 'dependency_analysis'
  | 'risk_assessment'
  | 'pattern_detection'
  | 'recommendation'
  | 'report_generation'
  | 'completed';

export type RiskLevel = 'low' | 'medium' | 'high' | 'critical';

export type SuggestionPriority = 'low' | 'medium' | 'high' | 'critical';

export type ReportFormat = 'markdown' | 'json' | 'html' | 'pdf';

// ============================================================================
// Upload Types
// ============================================================================

export interface FileUploadRequest {
  file: File;
  language?: string;
  metadata?: Record<string, any>;
}

export interface RepositoryUploadRequest {
  repository_url: string;
  branch?: string;
  access_token?: string;
  include_patterns?: string[];
  exclude_patterns?: string[];
}

export interface SnippetUploadRequest {
  code: string;
  language: string;
  filename?: string;
  metadata?: Record<string, any>;
}

export interface UploadResponse {
  job_id: string;
  status: JobStatus;
  message: string;
  file_count?: number;
  total_size_bytes?: number;
  created_at: string;
}

// ============================================================================
// Analysis Types
// ============================================================================

export interface AnalysisRequest {
  job_id: string;
  options?: {
    include_complexity?: boolean;
    include_dependencies?: boolean;
    include_risks?: boolean;
    include_suggestions?: boolean;
    target_language?: string;
    target_framework?: string;
  };
}

export interface AnalysisResponse {
  job_id: string;
  status: JobStatus;
  message: string;
  started_at: string;
  estimated_completion?: string;
}

// ============================================================================
// Job Types
// ============================================================================

export interface JobDetails {
  job_id: string;
  status: JobStatus;
  current_stage?: AnalysisStage;
  progress_percentage: number;
  created_at: string;
  updated_at: string;
  started_at?: string;
  completed_at?: string;
  error_message?: string;
  metadata?: {
    file_count?: number;
    total_lines?: number;
    languages?: string[];
    [key: string]: any;
  };
}

export interface ComplexityMetrics {
  cyclomatic_complexity: number;
  cognitive_complexity: number;
  lines_of_code: number;
  comment_ratio: number;
  maintainability_index: number;
}

export interface DependencyInfo {
  name: string;
  version?: string;
  type: 'internal' | 'external' | 'system';
  usage_count: number;
  is_deprecated?: boolean;
  replacement_suggestion?: string;
}

export interface RiskItem {
  risk_id: string;
  title: string;
  description: string;
  level: RiskLevel;
  category: string;
  file_path?: string;
  line_number?: number;
  code_snippet?: string;
  impact: string;
  likelihood: string;
  mitigation?: string;
}

export interface SuggestionItem {
  suggestion_id: string;
  title: string;
  description: string;
  priority: SuggestionPriority;
  category: string;
  file_path?: string;
  line_number?: number;
  current_code?: string;
  suggested_code?: string;
  rationale: string;
  effort_estimate?: string;
  benefits?: string[];
}

export interface JobResults {
  job_id: string;
  status: JobStatus;
  summary: {
    total_files: number;
    total_lines: number;
    languages: Record<string, number>;
    complexity_score: number;
    risk_count: number;
    suggestion_count: number;
  };
  complexity?: ComplexityMetrics;
  dependencies?: DependencyInfo[];
  risks?: RiskItem[];
  suggestions?: SuggestionItem[];
  analysis_duration_seconds?: number;
  completed_at?: string;
}

// ============================================================================
// Query Types
// ============================================================================

export interface QueryRequest {
  job_id: string;
  question: string;
  context?: {
    file_path?: string;
    line_range?: [number, number];
    focus_area?: string;
  };
}

export interface QueryResponse {
  query_id: string;
  job_id: string;
  question: string;
  answer: string;
  confidence: number;
  sources?: Array<{
    file_path: string;
    line_number?: number;
    snippet?: string;
  }>;
  related_risks?: string[];
  related_suggestions?: string[];
  timestamp: string;
}

export interface QueryHistory {
  job_id: string;
  queries: Array<{
    query_id: string;
    question: string;
    answer: string;
    timestamp: string;
  }>;
  total_count: number;
}

// ============================================================================
// Report Types
// ============================================================================

export interface ReportGenerationRequest {
  job_id: string;
  format: ReportFormat;
  options?: {
    include_summary?: boolean;
    include_complexity?: boolean;
    include_dependencies?: boolean;
    include_risks?: boolean;
    include_suggestions?: boolean;
    include_code_snippets?: boolean;
    group_by?: 'file' | 'category' | 'priority';
  };
}

export interface ReportResponse {
  report_id: string;
  job_id: string;
  format: ReportFormat;
  download_url: string;
  content?: string;
  size_bytes: number;
  generated_at: string;
}

export interface ReportMetadata {
  report_id: string;
  job_id: string;
  format: ReportFormat;
  size_bytes: number;
  generated_at: string;
  expires_at?: string;
}

// ============================================================================
// Health Check Types
// ============================================================================

export interface HealthCheckResponse {
  status: 'healthy' | 'degraded' | 'unhealthy';
  version: string;
  timestamp: string;
  services: {
    database: 'up' | 'down';
    redis?: 'up' | 'down';
    llm_provider: 'up' | 'down';
    mcp?: 'up' | 'down';
  };
}

// ============================================================================
// Error Types
// ============================================================================

export interface APIError {
  detail: string;
  status_code: number;
  error_code?: string;
  timestamp?: string;
}

export interface ValidationError {
  detail: Array<{
    loc: string[];
    msg: string;
    type: string;
  }>;
}
